window.__votdWeek && window.__votdWeek({"week":"2028-08-14","reading":"Alma 53–63","days":[{"d":"2028-08-14","ref":"Alma 55:15","b":"Alma","c":55,"v":15,"he":"וַיְהִי כַּאֲשֶׁר רָאוּ לָמָן וַאֲנָשָׁיו כִּי נִשְׁתַּכְּרוּ כֻלָּם וַיִּפְּלוּ בְּתַרְדֵּמָה עֲמֻקָּה וַיָּשׁוּבוּ אֶל־מוֹרוֹנִי וַיַּגִּידוּ לוֹ אֶת־כׇּל־אֲשֶׁר קָרָה׃","en":"And now when Laman and his men saw that they were all drunken, and were in a deep sleep, they returned to Moroni and told him all the things that had happened."},{"d":"2028-08-15","ref":"Alma 56:48","b":"Alma","c":56,"v":48,"he":"וַיִּשְׁנוּ לִי אֶת־דִּבְרֵי אִמּוֹתֵיהֶם לֵאמֹר אֵין לִבֵּנוּ תָּלוּי כִּי יָדְעוּ אִמּוֹתֵינוּ׃","en":"And they rehearsed unto me the words of their mothers, saying: We do not doubt our mothers knew it."},{"d":"2028-08-16","ref":"Alma 58:6","b":"Alma","c":58,"v":6,"he":"וַיִּהְיוּ הַלָּמָנִים יֹצְאִים עָלֵינוּ מֵעֵת לְעֵת מְבַקְשִׁים לְהַשְׁמִידֵנוּ בְּעׇרְמָה אַךְ לֹא יָכֹלְנוּ לְהִלָּחֵם בָּם בַּעֲבוּר מִקְלָטֵיהֶם וּמְצוּדוֹתֵיהֶם׃","en":"And the Lamanites were sallying forth against us from time to time, resolving by stratagem to destroy us; nevertheless we could not come to battle with them, because of their retreats and their strongholds."},{"d":"2028-08-17","ref":"Alma 59:6","b":"Alma","c":59,"v":6,"he":"גַּם־אֵלֶּה אֲשֶׁר אֻלְּצוּ לָנוּס מֵאֶרֶץ מַנְטִי וּמִסְּבִיבוֹתֶיהָ בָּאוּ וַיִּתְחַבְּרוּ אֶל־הַלָּמָנִים בַּחֵלֶק הַהוּא מִן־הָאָרֶץ׃","en":"Yea, even those who had been compelled to flee from the land of Manti, and from the land round about, had come over and joined the Lamanites in this part of the land."},{"d":"2028-08-18","ref":"Alma 61:3","b":"Alma","c":61,"v":3,"he":"אַךְ הִנֵּה יֵשׁ הַשְּׂמֵחִים בְּצָרוֹתֶיךָ אַף עַד־כִּי קָמוּ בְּמֶרֶד נֶגְדִּי וְגַם נֶגֶד בְּנֵי הַחֹפֶשׁ מֵעַמִּי הֵן וְרַבִּים מְאֹד הֵם אֲשֶׁר קָמוּ׃","en":"But behold, there are those who do joy in your afflictions, yea, insomuch that they have risen up in rebellion against me, and also those of my people who are freemen, yea, and those who have risen up are exceedingly numerous."},{"d":"2028-08-19","ref":"Alma 62:45","b":"Alma","c":62,"v":45,"he":"לָכֵן יָצְאוּ הֵילָמָן וְאֶחָיו וַיַּגִּידוּ אֶת־דְּבַר אֱלֹהִים בְּכֹחַ רַב לְהוֹכִיחַ עַם רַב בְּרִשְׁעָתָם אֲשֶׁר הֱבִיאָם לָשׁוּב מֵחַטֹּאתֵיהֶם וּלְהִטָּבֵל לַיהוָה אֱלֹהֵיהֶם׃","en":"Therefore, Helaman and his brethren went forth, and did declare the word of God with much power unto the convincing of many people of their wickedness, which did cause them to repent of their sins and to be baptized unto the Lord their God."},{"d":"2028-08-20","ref":"Alma 63:12","b":"Alma","c":63,"v":12,"he":"וְהִנֵּה כׇּל־הַחֲקוּקוֹת הָאֵלֶּה אֲשֶׁר הָיוּ בְּיַד הֵילָמָן נִכְתְּבוּ וְנִשְׁלְחוּ בֵּין בְּנֵי־הָאָדָם בְּכׇל־הָאָרֶץ מִלְּבַד הַחֲלָקִים אֲשֶׁר צִוָּה אַלְמָא לְבִלְתִּי יֵצְאוּ׃","en":"Now behold, all those engravings which were in the possession of Helaman were written and sent forth among the children of men throughout all the land, save it were those parts which had been commanded by Alma should not go forth."}]});
